      <WhyChooseUs />

      {/* About Us */}
      <About />

      {/* Cart */}
      <Cart
        cart={cart}
        removeFromCart={removeFromCart}
        updateQuantity={updateQuantity}
      />

      {/* Newsletter */}
      <Newsletter />

      {/* Footer */}
      <Footer />

    </div>
  );
}

export default App;
